head.b:skin:
:root {
  --aicon-bg: #0B0B0F;
  --aicon-header: #0E0E12;
  --aicon-surface: #111116;
  --aicon-card: #17171D;
  --aicon-card-alt: #1B1B21;
  --aicon-border: #27272A;
  --aicon-border-strong: #3F3F46;
  --aicon-text: #F5F5F5;
  --aicon-text-secondary: #A1A1AA;
  --aicon-text-muted: #71717A;
  --aicon-accent: #FF6B35;
  --aicon-accent-hover: #FF8558;
  --aicon-accent-soft: rgba(255, 107, 53, .12);
  --aicon-accent-line: rgba(255, 107, 53, .48);
  --aicon-focus: #FFB199;
  --aicon-max: 1280px;
  --aicon-reading: 760px;
  --aicon-wide: 960px;
  --aicon-header-height: 72px;
  --aicon-space-1: 4px;
  --aicon-space-2: 8px;
  --aicon-space-3: 12px;
  --aicon-space-4: 16px;
  --aicon-space-5: 24px;
  --aicon-space-6: 32px;
  --aicon-space-7: 48px;
  --aicon-space-8: 64px;
  --aicon-space-9: 80px;
  --aicon-space-10: 96px;
  --aicon-radius-sm: 6px;
  --aicon-radius-md: 10px;
  --aicon-radius-lg: 14px;
  --aicon-ease: cubic-bezier(.2,.8,.2,1);
  --aicon-duration: 180ms;
  --aicon-font: 'Poppins', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  --aicon-mono: 'SFMono-Regular', Consolas, 'Liberation Mono', monospace;
}

*, *::before, *::after { box-sizing: border-box; }
html { background: var(--aicon-bg); scroll-behavior: smooth; }
body {
  min-width: 320px;
  margin: 0;
  overflow-x: hidden;
  background: var(--aicon-bg);
  color: var(--aicon-text);
  font-family: var(--aicon-font);
  font-size: 16px;
  line-height: 1.65;
  text-rendering: optimizeLegibility;
  -webkit-font-smoothing: antialiased;
}
body, button, input, textarea, select { font-family: var(--aicon-font); }
a { color: inherit; text-decoration: none; }
button, input { font: inherit; }
button { cursor: pointer; }
img, svg, video, iframe { max-width: 100%; }
img { display: block; height: auto; }
svg { display: block; }
[hidden] { display: none !important; }
::selection { background: var(--aicon-accent); color: #160b06; }

.aicon-skip-link {
  position: fixed;
  top: var(--aicon-space-3);
  left: var(--aicon-space-3);
  z-index: 1000;
  transform: translateY(-160%);
  padding: 10px 14px;
  border-radius: var(--aicon-radius-sm);
  background: var(--aicon-accent);
  color: #160b06;
  font-size: 14px;
  font-weight: 700;
  transition: transform var(--aicon-duration) var(--aicon-ease);
}
.aicon-skip-link:focus { transform: translateY(0); }
.container {
  width: min(calc(100% - 48px), var(--aicon-max));
  margin-inline: auto;
}
.container--narrow { max-width: var(--aicon-reading); }
.container--wide { max-width: var(--aicon-wide); }
.visually-hidden {
  position: absolute !important;
  width: 1px !important;
  height: 1px !important;
  padding: 0 !important;
  margin: -1px !important;
  overflow: hidden !important;
  clip: rect(0, 0, 0, 0) !important;
  white-space: nowrap !important;
  border: 0 !important;
}
:focus-visible {
  outline: 2px solid var(--aicon-focus);
  outline-offset: 3px;
}

/* Header and navigation */
.site-header {
  position: sticky;
  top: 0;
  z-index: 100;
  border-bottom: 1px solid var(--aicon-border);
  background: rgba(14, 14, 18, .96);
  backdrop-filter: blur(12px);
}
.header-inner {
  display: grid;
  grid-template-columns: minmax(170px, 1fr) auto minmax(170px, 1fr);
  align-items: center;
  min-height: var(--aicon-header-height);
  gap: var(--aicon-space-5);
}
.brand {
  display: inline-flex;
  align-items: baseline;
  justify-self: start;
  gap: 9px;
  min-width: 0;
  transition: color var(--aicon-duration) ease;
}
.brand:hover { color: var(--aicon-accent-hover); }
.brand-word {
  color: var(--aicon-text);
  font-size: 21px;
  font-weight: 700;
  letter-spacing: -.055em;
  line-height: 1;
}
.brand-word::first-letter { color: var(--aicon-accent); }
.brand-subtitle {
  color: var(--aicon-text-muted);
  font-size: 10px;
  font-weight: 600;
  letter-spacing: .08em;
  line-height: 1;
  text-transform: uppercase;
  white-space: nowrap;
}
.primary-nav {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 2px;
  min-width: 0;
}
.nav-link {
  position: relative;
  display: inline-flex;
  align-items: center;
  min-height: 40px;
  padding: 8px 10px;
  border-radius: var(--aicon-radius-sm);
  color: var(--aicon-text-secondary);
  font-size: 13px;
  font-weight: 600;
  white-space: nowrap;
  transition: background var(--aicon-duration) ease, color var(--aicon-duration) ease;
}
.nav-link:hover,
.nav-link:focus-visible { background: var(--aicon-accent-soft); color: var(--aicon-text); }
.nav-link[aria-current='page'] { color: var(--aicon-accent); }
.header-actions {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: var(--aicon-space-2);
}
.icon-button {
  display: inline-grid;
  width: 40px;
  height: 40px;
  place-items: center;
  padding: 0;
  border: 1px solid transparent;
  border-radius: var(--aicon-radius-sm);
  background: transparent;
  color: var(--aicon-text-secondary);
  transition: background var(--aicon-duration) ease, border-color var(--aicon-duration) ease, color var(--aicon-duration) ease;
}
.icon-button:hover { border-color: var(--aicon-border-strong); background: var(--aicon-card); color: var(--aicon-text); }
.menu-button { display: none; }
.menu-button__line,
.menu-button__line::before,
.menu-button__line::after {
  display: block;
  width: 18px;
  height: 1.5px;
  background: currentColor;
  transition: transform var(--aicon-duration) ease;
}
.menu-button__line { position: relative; }
.menu-button__line::before,
.menu-button__line::after { position: absolute; content: ''; }
.menu-button__line::before { top: -6px; }
.menu-button__line::after { top: 6px; }
.menu-button[aria-expanded='true'] .menu-button__line { background: transparent; }
.menu-button[aria-expanded='true'] .menu-button__line::before { transform: translateY(6px) rotate(45deg); }
.menu-button[aria-expanded='true'] .menu-button__line::after { transform: translateY(-6px) rotate(-45deg); }
.mobile-menu {
  border-top: 1px solid var(--aicon-border);
  background: var(--aicon-header);
}
.mobile-menu__inner {
  display: grid;
  gap: 2px;
  padding-block: var(--aicon-space-3) var(--aicon-space-5);
}
.mobile-menu .nav-link { width: 100%; min-height: 44px; padding-inline: var(--aicon-space-3); }

/* Search dialog */
.search-dialog {
  position: fixed;
  inset: 0;
  z-index: 300;
  display: grid;
  place-items: start center;
  padding: 12vh 24px 24px;
  background: rgba(0, 0, 0, .72);
}
.search-dialog__panel {
  width: min(100%, 680px);
  border: 1px solid var(--aicon-border-strong);
  border-radius: var(--aicon-radius-lg);
  background: var(--aicon-surface);
  box-shadow: 0 24px 80px rgba(0, 0, 0, .42);
}
.search-dialog__top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--aicon-space-4);
  padding: var(--aicon-space-4) var(--aicon-space-5);
  border-bottom: 1px solid var(--aicon-border);
}
.search-dialog__title { margin: 0; font-size: 15px; font-weight: 600; }
.search-form { display: flex; align-items: center; gap: var(--aicon-space-3); padding: var(--aicon-space-5); }
.search-form__field {
  width: 100%;
  min-height: 48px;
  padding: 10px 14px;
  border: 1px solid var(--aicon-border-strong);
  border-radius: var(--aicon-radius-sm);
  outline: 0;
  background: var(--aicon-card);
  color: var(--aicon-text);
}
.search-form__field::placeholder { color: var(--aicon-text-muted); }
.search-form__field:focus { border-color: var(--aicon-accent); box-shadow: 0 0 0 3px var(--aicon-accent-soft); }
.button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 44px;
  gap: 9px;
  padding: 10px 16px;
  border: 1px solid transparent;
  border-radius: var(--aicon-radius-sm);
  font-size: 14px;
  font-weight: 700;
  line-height: 1.2;
  transition: background var(--aicon-duration) ease, border-color var(--aicon-duration) ease, color var(--aicon-duration) ease, transform var(--aicon-duration) ease;
}
.button--accent { background: var(--aicon-accent); color: #160b06; }
.button--accent:hover { background: var(--aicon-accent-hover); transform: translateY(-1px); }
.button--quiet { border-color: var(--aicon-border-strong); background: transparent; color: var(--aicon-text); }
.button--quiet:hover { border-color: var(--aicon-accent); color: var(--aicon-accent-hover); }

/* Homepage identity */
.home-hero {
  position: relative;
  overflow: hidden;
  padding: clamp(72px, 10vw, 128px) 0 clamp(64px, 9vw, 112px);
  border-bottom: 1px solid var(--aicon-border);
  background: var(--aicon-bg);
}
.home-hero::after {
  position: absolute;
  right: -140px;
  bottom: -220px;
  width: 430px;
  height: 430px;
  border: 1px solid var(--aicon-accent-line);
  border-radius: 50%;
  content: '';
  opacity: .55;
  pointer-events: none;
}
.home-hero__content { position: relative; z-index: 1; max-width: 820px; }
.eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 9px;
  margin: 0 0 var(--aicon-space-5);
  color: var(--aicon-accent);
  font-size: 12px;
  font-weight: 700;
  letter-spacing: .13em;
  line-height: 1.3;
  text-transform: uppercase;
}
.eyebrow::before { width: 24px; height: 1px; background: var(--aicon-accent); content: ''; }
.home-hero h1 {
  max-width: 820px;
  margin: 0;
  color: var(--aicon-text);
  font-size: clamp(2.25rem, 5.5vw, 4.2rem);
  font-weight: 600;
  letter-spacing: -.065em;
  line-height: 1.08;
}
.home-hero__lede {
  max-width: 650px;
  margin: var(--aicon-space-5) 0 0;
  color: var(--aicon-text-secondary);
  font-size: clamp(1rem, 1.5vw, 1.15rem);
  line-height: 1.75;
}
.home-hero__actions { display: flex; flex-wrap: wrap; gap: var(--aicon-space-3); margin-top: var(--aicon-space-7); }
.home-hero__rule {
  display: flex;
  align-items: center;
  gap: var(--aicon-space-3);
  margin-top: var(--aicon-space-8);
  color: var(--aicon-text-muted);
  font-size: 12px;
}
.home-hero__rule::before { width: 48px; height: 1px; background: var(--aicon-border-strong); content: ''; }

/* Shared sections */
.content-section { padding: var(--aicon-space-10) 0; }
.content-section + .content-section { border-top: 1px solid var(--aicon-border); }
.section-heading {
  display: flex;
  align-items: end;
  justify-content: space-between;
  gap: var(--aicon-space-5);
  margin-bottom: var(--aicon-space-6);
}
.section-heading__kicker {
  margin: 0 0 var(--aicon-space-2);
  color: var(--aicon-accent);
  font-size: 12px;
  font-weight: 700;
  letter-spacing: .11em;
  text-transform: uppercase;
}
.section-heading h2,
.section-heading h1 {
  margin: 0;
  color: var(--aicon-text);
  font-size: clamp(1.6rem, 3vw, 2.15rem);
  font-weight: 600;
  letter-spacing: -.045em;
  line-height: 1.2;
}
.section-heading__link {
  display: inline-flex;
  align-items: center;
  flex: 0 0 auto;
  gap: 7px;
  color: var(--aicon-text-secondary);
  font-size: 13px;
  font-weight: 600;
}
.section-heading__link::after { color: var(--aicon-accent); content: '→'; font-size: 17px; transition: transform var(--aicon-duration) ease; }
.section-heading__link:hover { color: var(--aicon-accent-hover); }
.section-heading__link:hover::after { transform: translateX(3px); }
.featured-grid { display: grid; grid-template-columns: minmax(0, 1.25fr) minmax(240px, .75fr); gap: var(--aicon-space-5); }
.featured-grid.is-single { grid-template-columns: 1fr; }
.featured-primary, .featured-secondary { min-width: 0; }
.featured-secondary { display: grid; gap: var(--aicon-space-4); align-content: start; }
.featured-secondary .post-card { height: 100%; }
.featured-secondary .post-card__media { aspect-ratio: 16 / 9; }
.featured-secondary .post-card__content { padding: var(--aicon-space-4); }
.featured-secondary .post-card h3 { font-size: 16px; }
.featured-secondary .post-card .post-excerpt { display: none; }
.featured-card {
  display: grid;
  grid-template-columns: minmax(0, 1.15fr) minmax(300px, .85fr);
  overflow: hidden;
  border: 1px solid var(--aicon-border);
  border-radius: var(--aicon-radius-lg);
  background: var(--aicon-card);
}
.featured-card__media,
.post-card__media {
  position: relative;
  display: block;
  overflow: hidden;
  background: var(--aicon-card-alt);
  aspect-ratio: 16 / 9;
}
.featured-card__media { min-height: 320px; }
.featured-card__media img,
.post-card__media img { width: 100%; height: 100%; object-fit: cover; transition: transform 300ms var(--aicon-ease); }
.featured-card:hover .featured-card__media img,
.post-card:hover .post-card__media img { transform: scale(1.025); }
.media-fallback {
  display: grid;
  width: 100%;
  height: 100%;
  min-height: 180px;
  place-items: center;
  color: var(--aicon-accent);
  font-size: 28px;
  font-weight: 700;
  letter-spacing: -.06em;
}
.featured-card__content { display: flex; flex-direction: column; justify-content: center; padding: clamp(24px, 4vw, 48px); }
.post-card__content { padding: var(--aicon-space-5); }
.post-label {
  display: inline-flex;
  align-items: center;
  width: fit-content;
  max-width: 100%;
  margin-bottom: var(--aicon-space-3);
  color: var(--aicon-accent);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: .095em;
  line-height: 1.3;
  text-transform: uppercase;
}
.post-label::before { width: 6px; height: 6px; margin-right: 7px; border-radius: 50%; background: var(--aicon-accent); content: ''; }
.featured-card h3,
.post-card h3 {
  margin: 0;
  color: var(--aicon-text);
  font-size: 20px;
  font-weight: 600;
  letter-spacing: -.035em;
  line-height: 1.32;
}
.featured-card h3 { font-size: clamp(1.65rem, 3.5vw, 2.65rem); line-height: 1.17; }
.featured-card h3 a:hover,
.post-card h3 a:hover { color: var(--aicon-accent-hover); }
.post-excerpt {
  display: -webkit-box;
  overflow: hidden;
  margin: var(--aicon-space-4) 0 0;
  color: var(--aicon-text-secondary);
  font-size: 14px;
  line-height: 1.7;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 3;
}
.featured-card .post-excerpt { font-size: 15px; }
.post-meta {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px 14px;
  margin-top: var(--aicon-space-5);
  color: var(--aicon-text-muted);
  font-size: 12px;
  line-height: 1.45;
}
.post-meta__item { display: inline-flex; align-items: center; gap: 6px; }
.post-meta__item + .post-meta__item::before { width: 3px; height: 3px; margin-right: 7px; border-radius: 50%; background: var(--aicon-border-strong); content: ''; }
.post-card {
  overflow: hidden;
  border: 1px solid var(--aicon-border);
  border-radius: var(--aicon-radius-md);
  background: var(--aicon-card);
  transition: border-color var(--aicon-duration) ease, transform var(--aicon-duration) var(--aicon-ease);
}
.post-card:hover { border-color: var(--aicon-accent-line); transform: translateY(-2px); }
.post-card__media { border-bottom: 1px solid var(--aicon-border); }
.post-grid { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: var(--aicon-space-5); }
.post-card--compact { height: 100%; }
.post-card--compact .post-card__content { padding: var(--aicon-space-4); }
.post-card--compact h3 { font-size: 16px; }
.post-card--compact .post-excerpt { display: none; }
.post-card--compact .post-meta { margin-top: var(--aicon-space-4); }
.topic-section { border-top: 1px solid var(--aicon-border); }
.topic-section .post-grid { grid-template-columns: repeat(4, minmax(0, 1fr)); }
.topic-empty { margin: 0; color: var(--aicon-text-muted); font-size: 14px; }
.js .topic-section:has(.post-card) .topic-empty { display: none; }
.js .topic-section:not(:has(.post-card)) { display: none; }
.js .topic-section.has-posts .topic-empty { display: none; }
.js .topic-section.is-empty { display: none; }

/* Newsletter and neutral empty states */
.newsletter-panel {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(260px, .7fr);
  gap: var(--aicon-space-7);
  align-items: center;
  padding: clamp(24px, 4vw, 40px);
  border: 1px solid var(--aicon-border);
  border-left: 3px solid var(--aicon-accent);
  border-radius: var(--aicon-radius-md);
  background: var(--aicon-surface);
}
.newsletter-panel h2 { margin: 0; font-size: clamp(1.35rem, 3vw, 2rem); letter-spacing: -.04em; line-height: 1.2; }
.newsletter-panel p { max-width: 620px; margin: var(--aicon-space-3) 0 0; color: var(--aicon-text-secondary); font-size: 14px; }
.newsletter-slot {
  min-height: 72px;
  padding: var(--aicon-space-4);
  border: 1px dashed var(--aicon-border-strong);
  border-radius: var(--aicon-radius-sm);
  color: var(--aicon-text-muted);
  font-size: 13px;
}
.newsletter-slot::before { display: none; }
.newsletter-slot__label { display: block; color: var(--aicon-accent); font-size: 12px; font-weight: 700; }
.newsletter-slot__hint { display: block; margin-top: 5px; color: var(--aicon-text-muted); font-size: 12px; }
.empty-state {
  padding: clamp(32px, 6vw, 64px) var(--aicon-space-5);
  border: 1px dashed var(--aicon-border-strong);
  border-radius: var(--aicon-radius-md);
  background: var(--aicon-surface);
  text-align: center;
}
.empty-state__mark { margin: 0 0 var(--aicon-space-3); color: var(--aicon-accent); font-size: 25px; font-weight: 700; letter-spacing: -.08em; }
.empty-state h2 { margin: 0; font-size: 21px; letter-spacing: -.03em; }
.empty-state .button { margin-top: var(--aicon-space-5); }
.empty-state p { max-width: 520px; margin: var(--aicon-space-3) auto 0; color: var(--aicon-text-secondary); font-size: 14px; }

/* Archive, label and search pages */
.archive-header { padding: var(--aicon-space-10) 0 var(--aicon-space-7); border-bottom: 1px solid var(--aicon-border); }
.archive-header h1 { max-width: 850px; margin: 0; font-size: clamp(2rem, 5vw, 3.25rem); font-weight: 600; letter-spacing: -.06em; line-height: 1.12; }
.archive-header__description { max-width: 680px; margin: var(--aicon-space-4) 0 0; color: var(--aicon-text-secondary); }
.archive-search { max-width: 680px; margin-top: var(--aicon-space-6); padding: var(--aicon-space-4); border: 1px solid var(--aicon-border); border-radius: var(--aicon-radius-md); background: var(--aicon-surface); }
.archive-search .search-form { padding: 0; }
.archive-results { padding: var(--aicon-space-8) 0 var(--aicon-space-10); }
.archive-results__message { margin: 0 0 var(--aicon-space-5); color: var(--aicon-text-muted); font-size: 13px; }
.topic-links { display: flex; flex-wrap: wrap; gap: var(--aicon-space-2); margin-top: var(--aicon-space-6); }
.topic-links a { padding: 7px 11px; border: 1px solid var(--aicon-border); border-radius: var(--aicon-radius-sm); color: var(--aicon-text-secondary); font-size: 12px; font-weight: 600; }
.topic-links a:hover { border-color: var(--aicon-accent-line); color: var(--aicon-accent-hover); }
.pagination { display: flex; justify-content: space-between; gap: var(--aicon-space-4); margin-top: var(--aicon-space-8); padding-top: var(--aicon-space-5); border-top: 1px solid var(--aicon-border); }
.pagination a { color: var(--aicon-text-secondary); font-size: 14px; font-weight: 600; }
.pagination a:hover { color: var(--aicon-accent-hover); }

/* Post and page templates */
.breadcrumbs {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 7px;
  padding: var(--aicon-space-6) 0 0;
  color: var(--aicon-text-muted);
  font-size: 12px;
}
.breadcrumbs__separator { color: var(--aicon-border-strong); }
.breadcrumbs a:hover { color: var(--aicon-accent-hover); }
.article-header { max-width: 900px; padding: var(--aicon-space-7) 0 var(--aicon-space-7); }
.article-header h1,
.page-header h1 { margin: 0; font-size: clamp(2rem, 5vw, 3.65rem); font-weight: 600; letter-spacing: -.065em; line-height: 1.12; }
.article-deck { max-width: 780px; margin: var(--aicon-space-5) 0 0; color: var(--aicon-text-secondary); font-size: 18px; line-height: 1.65; }
.article-meta { display: flex; flex-wrap: wrap; align-items: center; gap: 10px 17px; margin-top: var(--aicon-space-6); color: var(--aicon-text-muted); font-size: 13px; }
.author-meta { display: inline-flex; align-items: center; gap: 9px; color: var(--aicon-text-secondary); font-weight: 600; }
.author-meta__avatar { width: 28px; height: 28px; border: 1px solid var(--aicon-border); border-radius: 50%; object-fit: cover; }
.article-meta__item { display: inline-flex; align-items: center; gap: 6px; }
.article-meta__item + .article-meta__item::before { width: 3px; height: 3px; margin-right: 9px; border-radius: 50%; background: var(--aicon-border-strong); content: ''; }
.article-hero { width: 100%; max-height: 680px; margin: 0 auto var(--aicon-space-8); overflow: hidden; border: 1px solid var(--aicon-border); border-radius: var(--aicon-radius-md); background: var(--aicon-card); }
.article-hero img { width: 100%; max-height: 680px; object-fit: cover; }
.article-body-layout { display: grid; grid-template-columns: minmax(150px, 190px) minmax(0, var(--aicon-reading)); align-items: start; gap: var(--aicon-space-7); max-width: 100%; margin: 0 auto; }
.post-toc { position: sticky; top: calc(var(--aicon-header-height) + var(--aicon-space-5)); max-height: calc(100vh - var(--aicon-header-height) - 48px); overflow: auto; padding: var(--aicon-space-4); border: 1px solid var(--aicon-border); border-radius: var(--aicon-radius-sm); background: var(--aicon-surface); }
.post-toc summary { cursor: pointer; color: var(--aicon-text); font-size: 13px; font-weight: 700; }
.post-toc[open] summary { margin-bottom: var(--aicon-space-3); }
.post-toc ol { display: grid; gap: 7px; padding: 0; margin: 0; list-style: none; }
.post-toc li { margin: 0; }
.post-toc li[data-level='3'] { padding-left: 10px; }
.post-toc a { color: var(--aicon-text-muted); font-size: 11px; line-height: 1.45; }
.post-toc a:hover { color: var(--aicon-accent-hover); }
.post-body { min-width: 0; color: var(--aicon-text); font-size: 17px; line-height: 1.85; overflow-wrap: anywhere; }
.post-body > :first-child { margin-top: 0; }
.post-body p { margin: 0 0 1.35em; }
.post-body h2,
.post-body h3,
.post-body h4 { scroll-margin-top: calc(var(--aicon-header-height) + 24px); color: var(--aicon-text); font-weight: 600; letter-spacing: -.04em; line-height: 1.25; }
.post-body h2 { margin: 2em 0 .65em; font-size: clamp(1.55rem, 3vw, 2.1rem); }
.post-body h3 { margin: 1.7em 0 .55em; font-size: clamp(1.25rem, 2vw, 1.55rem); }
.post-body h4 { margin: 1.5em 0 .5em; font-size: 1.15rem; }
.post-body a { color: var(--aicon-accent-hover); text-decoration: underline; text-decoration-color: var(--aicon-accent-line); text-underline-offset: 3px; }
.post-body a:hover { color: var(--aicon-text); text-decoration-color: var(--aicon-accent); }
.post-body ul,
.post-body ol { padding-left: 1.35em; margin: 0 0 1.35em; }
.post-body li + li { margin-top: .45em; }
.post-body blockquote { margin: 1.7em 0; padding: 4px 0 4px 20px; border-left: 3px solid var(--aicon-accent); color: var(--aicon-text-secondary); font-size: 1.05em; }
.post-body img { max-width: 100%; height: auto; margin: 1.8em auto; border-radius: var(--aicon-radius-sm); }
.post-body figure { margin: 1.8em 0; }
.post-body figcaption { margin-top: -1.1em; color: var(--aicon-text-muted); font-size: 12px; text-align: center; }
.post-body hr { margin: 2.5em 0; border: 0; border-top: 1px solid var(--aicon-border); }
.post-body pre { position: relative; max-width: 100%; margin: 1.7em 0; overflow: auto; border: 1px solid var(--aicon-border); border-radius: var(--aicon-radius-sm); background: #0A0A0D; color: #E4E4E7; font: 13px/1.7 var(--aicon-mono); tab-size: 2; }
.post-body pre code { display: block; min-width: max-content; padding: var(--aicon-space-5); font: inherit; }
.post-body :not(pre) > code { padding: 2px 5px; border: 1px solid var(--aicon-border); border-radius: 4px; background: var(--aicon-card-alt); color: var(--aicon-accent-hover); font: .88em var(--aicon-mono); }
.code-copy {
  position: absolute;
  top: 8px;
  right: 8px;
  padding: 5px 8px;
  border: 1px solid var(--aicon-border-strong);
  border-radius: 4px;
  background: var(--aicon-card);
  color: var(--aicon-text-secondary);
  font: 11px var(--aicon-font);
}
.code-copy:hover { color: var(--aicon-accent-hover); }
.post-body table { display: block; width: 100%; max-width: 100%; margin: 1.7em 0; overflow-x: auto; border-collapse: collapse; border-spacing: 0; }
.post-body th,
.post-body td { min-width: 120px; padding: 10px 12px; border: 1px solid var(--aicon-border); text-align: left; vertical-align: top; }
.post-body th { background: var(--aicon-card); color: var(--aicon-text); font-weight: 600; }
.post-body td { background: var(--aicon-surface); }
.post-body iframe,
.post-body video { display: block; width: 100%; max-width: 100%; margin: 1.7em 0; border: 0; }
.post-body iframe { aspect-ratio: 16 / 9; height: auto; }
.post-body video { height: auto; }
.post-body details { margin: 1.2em 0; border: 1px solid var(--aicon-border); border-radius: var(--aicon-radius-sm); background: var(--aicon-surface); }
.post-body summary { cursor: pointer; padding: 12px 14px; color: var(--aicon-text); font-weight: 600; }
.post-body details > :not(summary) { margin-right: 14px; margin-left: 14px; }
.post-tools { display: flex; flex-wrap: wrap; align-items: center; gap: var(--aicon-space-3); margin: var(--aicon-space-8) 0 0; padding: var(--aicon-space-4) 0; border-top: 1px solid var(--aicon-border); border-bottom: 1px solid var(--aicon-border); }
.post-tools__label { margin-right: auto; color: var(--aicon-text-muted); font-size: 12px; font-weight: 600; }
.tool-button { min-height: 36px; padding: 7px 11px; border: 1px solid var(--aicon-border-strong); border-radius: var(--aicon-radius-sm); background: transparent; color: var(--aicon-text-secondary); font-size: 12px; font-weight: 600; }
.tool-button:hover { border-color: var(--aicon-accent); color: var(--aicon-accent-hover); }
.post-tags { display: flex; flex-wrap: wrap; gap: var(--aicon-space-2); margin-top: var(--aicon-space-6); }
.post-tag { padding: 6px 9px; border: 1px solid var(--aicon-border); border-radius: 4px; color: var(--aicon-text-secondary); font-size: 12px; }
.post-tag:hover { border-color: var(--aicon-accent-line); color: var(--aicon-accent-hover); }
.author-panel { display: flex; align-items: center; gap: var(--aicon-space-4); max-width: var(--aicon-reading); margin: var(--aicon-space-8) auto 0; padding: var(--aicon-space-5); border: 1px solid var(--aicon-border); border-radius: var(--aicon-radius-md); background: var(--aicon-surface); }
.author-panel__avatar { width: 48px; height: 48px; flex: 0 0 48px; border: 1px solid var(--aicon-border); border-radius: 50%; object-fit: cover; }
.author-panel__mark { display: grid; width: 48px; height: 48px; flex: 0 0 48px; place-items: center; border: 1px solid var(--aicon-accent-line); border-radius: 50%; color: var(--aicon-accent); font-size: 14px; font-weight: 700; }
.author-panel__kicker { margin: 0; color: var(--aicon-accent); font-size: 11px; font-weight: 700; letter-spacing: .1em; text-transform: uppercase; }
.author-panel h2 { margin: 2px 0 0; font-size: 17px; letter-spacing: -.025em; }
.author-panel p:last-child { margin: 3px 0 0; color: var(--aicon-text-muted); font-size: 12px; }
.related-section { margin: var(--aicon-space-10) 0 0; padding-top: var(--aicon-space-7); border-top: 1px solid var(--aicon-border); }
.related-grid { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: var(--aicon-space-4); }
.related-card { display: block; padding: var(--aicon-space-4); border: 1px solid var(--aicon-border); border-radius: var(--aicon-radius-sm); background: var(--aicon-card); }
.related-card:hover { border-color: var(--aicon-accent-line); }
.related-card__label { color: var(--aicon-accent); font-size: 11px; font-weight: 700; text-transform: uppercase; }
.related-card h3 { margin: 7px 0 0; font-size: 15px; line-height: 1.4; }
.related-card time { display: block; margin-top: 9px; color: var(--aicon-text-muted); font-size: 11px; }
.comments { max-width: var(--aicon-reading); margin: var(--aicon-space-10) auto 0; padding-top: var(--aicon-space-7); border-top: 1px solid var(--aicon-border); }
.comments h2 { margin: 0 0 var(--aicon-space-5); font-size: 22px; letter-spacing: -.03em; }
.comments iframe { max-width: 100%; }
.page-shell { padding-bottom: var(--aicon-space-10); }
.page-header { max-width: var(--aicon-reading); padding: var(--aicon-space-7) 0; }
.page-body-wrap { max-width: var(--aicon-reading); }

/* Footer */
.site-footer { margin-top: var(--aicon-space-10); border-top: 1px solid var(--aicon-border); background: var(--aicon-header); }
.footer-main { display: grid; grid-template-columns: minmax(220px, 1.4fr) repeat(3, minmax(130px, 1fr)); gap: var(--aicon-space-7); padding: var(--aicon-space-9) 0 var(--aicon-space-8); }
.footer-brand p { max-width: 300px; margin: var(--aicon-space-4) 0 0; color: var(--aicon-text-muted); font-size: 13px; }
.footer-column h2 { margin: 0 0 var(--aicon-space-4); color: var(--aicon-text); font-size: 13px; font-weight: 700; letter-spacing: .04em; text-transform: uppercase; }
.footer-links { display: grid; gap: 8px; padding: 0; margin: 0; list-style: none; }
.footer-links a { color: var(--aicon-text-muted); font-size: 13px; }
.footer-links a:hover { color: var(--aicon-accent-hover); }
.footer-bottom { display: flex; flex-wrap: wrap; justify-content: space-between; gap: var(--aicon-space-3); padding: var(--aicon-space-4) 0; border-top: 1px solid var(--aicon-border); color: var(--aicon-text-muted); font-size: 12px; }
.footer-bottom p { margin: 0; }

/* Blogger widget normalization */
.widget, .Blog, .blog-posts, .post-outer, .post { margin: 0; padding: 0; }
.blog-pager { display: none; }
.footer-pages .widget { margin: 0; }
.footer-pages .widget h2 { display: none; }

@media (max-width: 1120px) {
  .header-inner { grid-template-columns: minmax(160px, 1fr) auto; }
  .primary-nav { display: none; }
  .header-actions { justify-self: end; }
  .menu-button { display: inline-grid; }
  .topic-section .post-grid { grid-template-columns: repeat(3, minmax(0, 1fr)); }
  .footer-main { grid-template-columns: minmax(220px, 1.25fr) repeat(3, minmax(120px, 1fr)); }
}
@media (max-width: 900px) {
  .featured-grid { grid-template-columns: 1fr; }
  .featured-card { grid-template-columns: 1fr; }
  .featured-card__media { min-height: 0; }
  .article-body-layout { grid-template-columns: 1fr; gap: var(--aicon-space-5); }
  .post-toc { position: static; max-height: none; }
  .post-toc[open] { margin-bottom: 0; }
  .newsletter-panel { grid-template-columns: 1fr; gap: var(--aicon-space-5); }
  .footer-main { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .footer-brand { grid-column: 1 / -1; }
}
@media (max-width: 640px) {
  .container { width: min(calc(100% - 32px), var(--aicon-max)); }
  .header-inner { min-height: 64px; }
  .brand-subtitle { display: none; }
  .header-actions { gap: 0; }
  .icon-button { width: 38px; height: 38px; }
  .home-hero { padding: 64px 0 72px; }
  .home-hero h1 { font-size: clamp(2.2rem, 11vw, 3.1rem); }
  .home-hero__actions .button { flex: 1 1 145px; }
  .content-section { padding: 64px 0; }
  .section-heading { align-items: start; flex-direction: column; gap: var(--aicon-space-3); }
  .section-heading__link { align-self: flex-start; }
  .post-grid,
  .topic-section .post-grid,
  .related-grid { grid-template-columns: 1fr; }
  .featured-card__content { padding: 24px; }
  .featured-card h3 { font-size: 1.8rem; }
  .search-dialog { padding: 7vh 16px 16px; }
  .search-form { flex-wrap: wrap; }
  .search-form .button { width: 100%; }
  .archive-header { padding-top: 64px; }
  .article-header h1, .page-header h1 { font-size: clamp(2rem, 10vw, 2.65rem); }
  .article-deck { font-size: 16px; }
  .post-body { font-size: 16px; line-height: 1.8; }
  .post-tools__label { width: 100%; }
  .footer-main { grid-template-columns: 1fr 1fr; gap: var(--aicon-space-6) var(--aicon-space-4); }
  .footer-brand { grid-column: 1 / -1; }
  .footer-bottom { flex-direction: column; }
}
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { scroll-behavior: auto !important; transition-duration: .01ms !important; animation-duration: .01ms !important; animation-iteration-count: 1 !important; }
}

body.script:
(function () {
  'use strict';

  var body = document.body;
  var menuToggle = document.querySelector('[data-menu-toggle]');
  var mobileMenu = document.getElementById('mobile-menu');
  var searchDialog = document.getElementById('search-dialog');
  var searchInput = document.getElementById('aicon-search-input');
  var lastFocused = null;

  function setMenu(open) {
    if (!menuToggle || !mobileMenu) return;
    menuToggle.setAttribute('aria-expanded', String(open));
    menuToggle.setAttribute('aria-label', open ? 'Close menu' : 'Open menu');
    mobileMenu.hidden = !open;
  }

  if (menuToggle) {
    menuToggle.addEventListener('click', function () {
      setMenu(mobileMenu.hidden);
    });
  }

  if (mobileMenu) {
    mobileMenu.addEventListener('click', function (event) {
      if (event.target.closest('a')) setMenu(false);
    });
  }

  function setSearch(open) {
    if (!searchDialog) return;
    if (open) {
      lastFocused = document.activeElement;
      searchDialog.hidden = false;
      searchDialog.setAttribute('aria-hidden', 'false');
      body.style.overflow = 'hidden';
      window.setTimeout(function () { if (searchInput) searchInput.focus(); }, 20);
    } else {
      searchDialog.hidden = true;
      searchDialog.setAttribute('aria-hidden', 'true');
      body.style.overflow = '';
      if (lastFocused && typeof lastFocused.focus === 'function') lastFocused.focus();
    }
  }

  document.querySelectorAll('[data-search-open]').forEach(function (button) {
    button.addEventListener('click', function () { setSearch(true); });
  });
  document.querySelectorAll('[data-search-close]').forEach(function (button) {
    button.addEventListener('click', function () { setSearch(false); });
  });
  if (searchDialog) {
    searchDialog.addEventListener('click', function (event) {
      if (event.target === searchDialog) setSearch(false);
    });
  }
  document.addEventListener('keydown', function (event) {
    if (event.key === 'Escape') {
      if (searchDialog && !searchDialog.hidden) setSearch(false);
      if (mobileMenu && !mobileMenu.hidden) setMenu(false);
    }
    if ((event.ctrlKey || event.metaKey) && event.key.toLowerCase() === 'k') {
      event.preventDefault();
      setSearch(searchDialog && searchDialog.hidden);
    }
  });

  document.querySelectorAll('.featured-grid').forEach(function (grid) {
    var secondary = grid.querySelector('.featured-secondary');
    if (!secondary || !secondary.querySelector('.post-card')) grid.classList.add('is-single');
  });

  document.querySelectorAll('.topic-section').forEach(function (section) {
    if (section.querySelector('.post-card')) section.classList.add('has-posts');
    else section.classList.add('is-empty');
  });

  document.querySelectorAll('.js-updated-date').forEach(function (target) {
    var date = new Date(target.getAttribute('datetime'));
    if (!isNaN(date.getTime())) target.textContent = date.toLocaleDateString(undefined, { year: 'numeric', month: 'long', day: 'numeric' });
  });

  document.querySelectorAll('.js-reading-time').forEach(function (target) {
    var article = target.closest('.article-page');
    var content = article && article.querySelector('.post-body');
    if (!content) return;
    var words = content.textContent.trim().split(/\s+/).filter(Boolean).length;
    if (words) target.textContent = Math.max(1, Math.ceil(words / 225)) + ' min read';
  });

  var toc = document.getElementById('post-toc');
  var tocList = toc && toc.querySelector('.js-toc-list');
  var postBody = document.querySelector('.post-page .post-body') || document.querySelector('.article-page .post-body');
  if (toc && tocList && postBody) {
    var headings = postBody.querySelectorAll('h2, h3');
    var usedIds = {};
    Array.prototype.forEach.call(headings, function (heading) {
      var text = heading.textContent.trim();
      if (!text) return;
      var base = heading.id || text.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '') || 'section';
      var id = base;
      var count = 2;
      while (usedIds[id] || (document.getElementById(id) && document.getElementById(id) !== heading)) {
        id = base + '-' + count;
        count += 1;
      }
      usedIds[id] = true;
      heading.id = id;
      var li = document.createElement('li');
      li.setAttribute('data-level', heading.tagName === 'H3' ? '3' : '2');
      var link = document.createElement('a');
      link.href = '#' + id;
      link.textContent = text;
      li.appendChild(link);
      tocList.appendChild(li);
    });
    if (tocList.children.length) {
      toc.hidden = false;
      toc.open = window.matchMedia('(min-width: 901px)').matches;
    }
  }

  document.querySelectorAll('.post-body pre').forEach(function (pre) {
    var code = pre.querySelector('code');
    if (!code || pre.querySelector('.code-copy')) return;
    var copy = document.createElement('button');
    copy.className = 'code-copy';
    copy.type = 'button';
    copy.textContent = 'Copy';
    copy.setAttribute('aria-label', 'Copy code');
    copy.addEventListener('click', function () {
      var value = code.textContent;
      var done = function () {
        copy.textContent = 'Copied';
        window.setTimeout(function () { copy.textContent = 'Copy'; }, 1400);
      };
      if (navigator.clipboard && window.isSecureContext) {
        navigator.clipboard.writeText(value).then(done).catch(function () {});
      } else {
        var area = document.createElement('textarea');
        area.value = value;
        area.setAttribute('readonly', '');
        area.style.position = 'fixed';
        area.style.opacity = '0';
        document.body.appendChild(area);
        area.select();
        try { document.execCommand('copy'); done(); } catch (error) {}
        document.body.removeChild(area);
      }
    });
    pre.appendChild(copy);
  });

  function copyText(value, button) {
    var done = function () {
      var original = button.textContent;
      button.textContent = 'Copied';
      window.setTimeout(function () { button.textContent = original; }, 1400);
    };
    if (navigator.clipboard && window.isSecureContext) {
      navigator.clipboard.writeText(value).then(done).catch(function () {});
    } else {
      var area = document.createElement('textarea');
      area.value = value;
      area.setAttribute('readonly', '');
      area.style.position = 'fixed';
      area.style.opacity = '0';
      document.body.appendChild(area);
      area.select();
      try { document.execCommand('copy'); done(); } catch (error) {}
      document.body.removeChild(area);
    }
  }

  document.querySelectorAll('[data-copy-post]').forEach(function (button) {
    button.addEventListener('click', function () { copyText(button.getAttribute('data-post-url') || window.location.href, button); });
  });
  document.querySelectorAll('[data-share-post]').forEach(function (button) {
    button.addEventListener('click', function () {
      var url = button.getAttribute('data-post-url') || window.location.href;
      var title = document.title;
      if (navigator.share) {
        navigator.share({ title: title, url: url }).catch(function () {});
      } else {
        copyText(url, button);
      }
    });
  });

  var related = document.querySelector('.js-related');
  var relatedGrid = related && related.querySelector('.js-related-grid');
  var home = body.getAttribute('data-blog-home');
  if (related && relatedGrid && home) {
    var label = related.getAttribute('data-related-label');
    var feedUrl = new URL('feeds/posts/default/-/' + encodeURIComponent(label), home);
    feedUrl.searchParams.set('alt', 'json');
    feedUrl.searchParams.set('max-results', '6');
    fetch(feedUrl.toString(), { credentials: 'same-origin' }).then(function (response) {
      if (!response.ok) throw new Error('Related feed unavailable');
      return response.json();
    }).then(function (data) {
      var entries = data.feed && data.feed.entry ? data.feed.entry : [];
      var current = window.location.href.replace(/\/$/, '');
      entries.filter(function (entry) {
        var alternate = (entry.link || []).find(function (link) { return link.rel === 'alternate'; });
        return alternate && alternate.href.replace(/\/$/, '') !== current;
      }).slice(0, 3).forEach(function (entry) {
        var alternate = (entry.link || []).find(function (link) { return link.rel === 'alternate'; });
        if (!alternate) return;
        var card = document.createElement('a');
        card.className = 'related-card';
        card.href = alternate.href;
        var labelNode = document.createElement('span');
        labelNode.className = 'related-card__label';
        labelNode.textContent = label;
        var title = document.createElement('h3');
        title.textContent = entry.title && entry.title.$t ? entry.title.$t : '';
        var time = document.createElement('time');
        time.textContent = entry.published && entry.published.$t ? new Date(entry.published.$t).toLocaleDateString() : '';
        card.appendChild(labelNode);
        card.appendChild(title);
        card.appendChild(time);
        relatedGrid.appendChild(card);
      });
      if (relatedGrid.children.length) related.hidden = false;
    }).catch(function () {});
  }
}());
